import React, { useState } from 'react';
import axios from 'axios';

axios.defaults.withCredentials = true;

axios.interceptors.request.use((config) => {
  const csrfToken = document.cookie
    .split('; ')
    .find(row => row.startsWith('csrftoken='))
    ?.split('=')[1];

  if (csrfToken) {
    config.headers['X-CSRFToken'] = csrfToken;
  }

  return config;
});

export default function UploadForm(){
  const [file, setFile] = useState(null);
  const [color, setColor] = useState('bw');
  const [status, setStatus] = useState('idle');
  const [order, setOrder] = useState(null);
  const [paymentLinkUrl, setPaymentLinkUrl] = useState(null);

  const upload = async () =>{
    if(!file) return;
    try{
      // Get CSRF cookie from Django
      await axios.get('/api/csrf/');
      setStatus('getting presign');
      const pres = await axios.post('/api/uploads/presign/');
      const file_key = pres.data.file_key;
      setStatus('uploading file');
      if(pres.data.upload_url){
        const uploadUrl = pres.data.upload_url;
        // If the upload URL is a local backend endpoint (contains /api/uploads/local), use multipart POST
        if (uploadUrl.includes('/api/uploads/local/')){
          const form = new FormData();
          form.append('file', file);
          await axios.post(uploadUrl, form, { headers: { 'Content-Type': 'multipart/form-data' } });
        } else {
          // For S3 presigned URL use PUT with file bytes
          await axios.put(uploadUrl, file, {headers:{'Content-Type':'application/pdf'}});
        }
      }
      // create order
      setStatus('creating order');
      const resp = await axios.post('/api/orders/', {file_key, pages_spec:'all', color_mode: color});
      setOrder(resp.data.order);
      setStatus('order created');

      // If Razorpay order info returned, open Razorpay Checkout or show payment link QR
      const payInfo = resp.data.pay_info;
      try{
        const rp = payInfo && payInfo.razorpay;
        const rpOrderId = rp && rp.order_id;
        const keyId = rp && rp.key_id;
        const amountPaise = resp.data.order.price_cents; // already in paise
        const orderId = resp.data.order.id;

        // Check for payment link (short_url) first
        const link = payInfo && payInfo.link;
        const shortUrl = link && (link.short_url || link.shortUrl || link.shorturl || link.shortURL || link.shorturl?.toString());
        if(shortUrl){
          // show QR for the short URL
          setPaymentLinkUrl(shortUrl);
          setStatus('payment link generated');
          return;
        }

        if(rpOrderId && keyId){
          // load Razorpay Checkout JS
          const scriptUrl = 'https://checkout.razorpay.com/v1/checkout.js';
          await new Promise((resolve, reject) => {
            if(window.Razorpay){
              return resolve();
            }
            const s = document.createElement('script');
            s.src = scriptUrl;
            s.onload = () => resolve();
            s.onerror = () => reject(new Error('Failed to load Razorpay Checkout script'));
            document.body.appendChild(s);
          });

          const options = {
            key: keyId,
            amount: amountPaise,
            currency: 'INR',
            name: 'Print Kiosk',
            description: `Order ${orderId}`,
            order_id: rpOrderId,
            handler: async function(response){
              try{
                // send to backend to verify signature and capture
                await axios.post('/api/payments/razorpay/confirm/', {
                  order_id: orderId,
                  razorpay_payment_id: response.razorpay_payment_id,
                  razorpay_order_id: response.razorpay_order_id,
                  razorpay_signature: response.razorpay_signature
                });
                alert('Payment confirmed');
              }catch(err){
                console.error('Confirm error', err);
                alert('Payment verification failed');
              }
            },
            modal: { 
              ondismiss: function(){ console.log('Payment popup closed'); }
            }
          };

          const rzp = new window.Razorpay(options);
          rzp.open();
        }
      } catch(e){
        console.error('Razorpay flow error', e);
      }

    }catch(err){
      console.error(err);
      setStatus('ERROR');
      alert(err.response && err.response.data ? JSON.stringify(err.response.data) : err.message);
    }
  }

  return (
    <div>
      <input type="file" accept="application/pdf" onChange={e=>setFile(e.target.files[0])} />
      <div>
        <label><input type="radio" checked={color==='bw'} onChange={()=>setColor('bw')} /> BW</label>
        <label style={{marginLeft:10}}><input type="radio" checked={color==='color'} onChange={()=>setColor('color')} /> Color</label>
      </div>
      <button onClick={upload}>Upload & Create Order</button>
      <div>Status: {status}</div>
      {order && <pre>{JSON.stringify(order,null,2)}</pre>}
      {paymentLinkUrl && (
        <div style={{marginTop:20}}>
          <h3>Scan to pay (Razorpay)</h3>
          <a href={paymentLinkUrl} target="_blank" rel="noreferrer">Open payment link</a>
          <div style={{marginTop:10}}>
            <img src={`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(paymentLinkUrl)}`} alt="payment-qr" />
          </div>
        </div>
      )}
    </div>
  )
}
